html, body, #root {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  min-height: 100%;
  overflow: hidden;
  background: transparent;
  font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  box-sizing: border-box;
}
* { box-sizing: border-box; }

.chat-app {
  height: 100%;
  min-height: 100%;
  display: flex;
  flex-direction: column;
  background: #ffffff;
}

.thread {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 14px 16px 8px;
  scrollbar-width: thin;
  scrollbar-color: #cbd5e1 transparent;
}
.thread::-webkit-scrollbar { width: 6px; }
.thread::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 99px; }

.row {
  width: 100%;
  display: flex;
  margin: 6px 0 14px;
}
.row.assistant { justify-content: flex-start; }
.row.user { justify-content: flex-end; }

.message-wrap {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  max-width: 82%;
}
.row.user .message-wrap { flex-direction: row-reverse; }

.avatar {
  width: 30px;
  height: 30px;
  border-radius: 9px;
  flex: 0 0 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 800;
  margin-top: 1px;
}
.assistant .avatar {
  background: #eaf1ff;
  color: #0759d9;
}
.user .avatar {
  background: #0f294f;
  color: #ffffff;
}

.bubble {
  padding: 11px 13px;
  border-radius: 13px;
  font-size: 13px;
  line-height: 1.52;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.assistant .bubble {
  background: #f5f7fb;
  color: #263850;
  border: 1px solid #e3e8f0;
  border-top-left-radius: 4px;
}
.user .bubble {
  background: #0759d9;
  color: #ffffff;
  border: 1px solid #0759d9;
  border-top-right-radius: 4px;
}
.bubble.status {
  background: #f8fafc;
  color: #53657c;
  border-style: dashed;
}
.bubble-title {
  margin-bottom: 5px;
  font-weight: 700;
  color: #081b42;
}

.typing {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 10px 39px;
  color: #7b8798;
  font-size: 12px;
}
.dots {
  display: inline-flex;
  gap: 4px;
  padding: 7px 9px;
  border-radius: 10px;
  background: #f5f7fb;
  border: 1px solid #e3e8f0;
}
.dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #7e8ca1;
  animation: pulse 1.1s infinite ease-in-out;
}
.dot:nth-child(2) { animation-delay: .12s; }
.dot:nth-child(3) { animation-delay: .24s; }
@keyframes pulse {
  0%, 70%, 100% { opacity: .25; transform: translateY(0); }
  35% { opacity: 1; transform: translateY(-2px); }
}

.composer-wrap {
  flex: 0 0 auto;
  padding: 10px 14px 14px;
  border-top: 1px solid #edf1f6;
  background: #ffffff;
}
.composer {
  min-height: 46px;
  display: flex;
  align-items: flex-end;
  gap: 8px;
  padding: 6px 6px 6px 12px;
  border: 1px solid #cbd5e1;
  border-radius: 10px;
  background: #ffffff;
  transition: border-color .15s ease, box-shadow .15s ease;
}
.composer:focus-within {
  border-color: #6c91e8;
  box-shadow: 0 0 0 2px rgba(7,89,217,.08);
}
textarea {
  flex: 1;
  min-height: 31px;
  max-height: 84px;
  resize: none;
  border: 0;
  outline: 0;
  padding: 6px 2px;
  font: inherit;
  font-size: 13px;
  line-height: 1.45;
  color: #263850;
  background: transparent;
}
textarea::placeholder { color: #94a0b2; }

.send {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  border: 0;
  border-radius: 8px;
  background: #0759d9;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 17px;
  font-weight: 700;
}
.send:disabled {
  cursor: not-allowed;
  opacity: .45;
}

