import React from 'https://cdn.jsdelivr.net/npm/react@18.2.0/+esm';
import ReactDOM from 'https://cdn.jsdelivr.net/npm/react-dom@18.2.0/+esm';

function ChatApp() {
  const initial = Array.isArray(appsmith.model?.messages) ? appsmith.model.messages : [];
  const [messages, setMessages] = React.useState(initial);
  const [draft, setDraft] = React.useState('');
  const [thinking, setThinking] = React.useState(false);
  const endRef = React.useRef(null);

  React.useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' });
  }, [messages, thinking]);

  React.useEffect(() => {
    appsmith.onModelChange((model, prevModel) => {
      if (
        Array.isArray(model?.messages) &&
        JSON.stringify(model.messages) !== JSON.stringify(prevModel?.messages)
      ) {
        setMessages(model.messages);
      }
    });
  }, []);

  const send = () => {
    const text = draft.trim();
    if (!text) return;

    const nextMessage = {
      id: 'user-' + Date.now(),
      role: 'user',
      text
    };

    setMessages(prev => [...prev, nextMessage]);
    setDraft('');
    setThinking(true);

    appsmith.updateModel({
      ...appsmith.model,
      messages: [...messages, nextMessage],
      lastMessage: text
    });

    appsmith.triggerEvent('onMessageSend', { message: text });

    // Demo-only visual typing state. Real AI response will replace this when wired.
    window.setTimeout(() => setThinking(false), 1200);
  };

  const onKeyDown = (event) => {
    if (event.key === 'Enter' && !event.shiftKey) {
      event.preventDefault();
      send();
    }
  };

  return React.createElement(
    'div',
    { className: 'chat-app' },

    React.createElement(
      'div',
      { className: 'thread' },

      ...messages.map((m, i) => {
        const role = m.role === 'user' ? 'user' : 'assistant';
        return React.createElement(
          'div',
          { className: `row ${role}`, key: m.id || i },
          React.createElement(
            'div',
            { className: 'message-wrap' },
            React.createElement('div', { className: 'avatar' }, role === 'user' ? 'Y' : 'AI'),
            React.createElement(
              'div',
              { className: `bubble${m.variant === 'status' ? ' status' : ''}` },
              m.title
                ? React.createElement('div', { className: 'bubble-title' }, m.title)
                : null,
              React.createElement('div', null, m.text || '')
            )
          )
        );
      }),

      thinking
        ? React.createElement(
            'div',
            { className: 'typing' },
            React.createElement(
              'div',
              { className: 'dots' },
              React.createElement('span', { className: 'dot' }),
              React.createElement('span', { className: 'dot' }),
              React.createElement('span', { className: 'dot' })
            ),
            React.createElement('span', null, 'Assistant is thinking…')
          )
        : null,

      React.createElement('div', { ref: endRef })
    ),

    React.createElement(
      'div',
      { className: 'composer-wrap' },
      React.createElement(
        'div',
        { className: 'composer' },
        React.createElement('textarea', {
          value: draft,
          rows: 1,
          placeholder: appsmith.model?.placeholder || 'Type a question or instruction...',
          onChange: e => setDraft(e.target.value),
          onKeyDown
        }),
        React.createElement(
          'button',
          {
            className: 'send',
            disabled: !draft.trim(),
            onClick: send,
            title: 'Send'
          },
          '➜'
        )
      )
    )
  );
}

appsmith.onReady(() => {
  ReactDOM.render(
    React.createElement(ChatApp),
    document.getElementById('root')
  );
});

